// PHYSICS — batch 1. Keys: id, t topic, d level (1 Foundation, 2 Advanced, 3 Olympiad), ty type,
// q question, o options, a answer index, e explanation, m misconception, h hints, s seconds,
// iq Science-IQ problem, v independent verification expression for the numerical answer.
// g = 10 m/s² wherever a question says so; otherwise 9.8 m/s².
export default [
  // ---------------------------------------------------------------- Motion
  { id: 'PHY-001', t: 'Motion', d: 1, ty: 'mcq', s: 40,
    q: 'A runner completes exactly one lap of a 400 m circular track in 80 s. What are her average speed and average velocity for the lap?',
    o: ['5 m/s and 5 m/s', '5 m/s and 0 m/s', '0 m/s and 5 m/s', '2.5 m/s and 0 m/s'], a: 1,
    e: 'Average speed = total distance ÷ time = 400 m ÷ 80 s = 5 m/s. Average velocity = displacement ÷ time; after one full lap she is back at the start, so displacement = 0 and average velocity = 0.',
    m: 'Speed and velocity are not interchangeable: velocity uses displacement (with direction), which is zero for a closed loop.',
    h: ['Where does she finish compared with where she started?', 'Velocity uses displacement, speed uses distance.'] },
  { id: 'PHY-002', t: 'Motion', d: 2, ty: 'numerical', s: 60, v: '2*100/10',
    q: 'A car starts from rest, accelerates uniformly and covers 100 m in the first 10 s. What is its speed at the end of the 10 s?',
    o: ['10 m/s', '20 m/s', '15 m/s', '40 m/s'], a: 1,
    e: 's = ½at² gives 100 = ½ × a × 100, so a = 2 m/s². Then v = at = 2 × 10 = 20 m/s. Shortcut: for uniform acceleration from rest, average speed = v/2, so v = 2 × (100/10) = 20 m/s.',
    m: '10 m/s is the AVERAGE speed. Because the car started from rest, its final speed is twice the average.',
    h: ['Use s = ut + ½at² with u = 0.', 'Average speed for uniform acceleration = (u + v)/2.'] },
  { id: 'PHY-003', t: 'Motion', d: 2, ty: 'data', s: 75, v: '0.5*2*8+2*8+0.5*2*8',
    q: 'A cyclist’s velocity was recorded every 2 s (the velocity changes uniformly between readings). What is the total displacement in the 6 s?',
    tb: { head: ['Time (s)', '0', '2', '4', '6'], rows: [['Velocity (m/s)', 0, 8, 8, 0]] },
    o: ['24 m', '32 m', '48 m', '16 m'], a: 1,
    e: 'Displacement = area under the velocity–time graph. 0–2 s: triangle ½ × 2 × 8 = 8 m; 2–4 s: rectangle 2 × 8 = 16 m; 4–6 s: triangle 8 m. Total = 32 m.',
    m: '48 m comes from treating the velocity as 8 m/s for the whole 6 s; the speeding-up and slowing-down phases only count half.',
    h: ['Sketch the v–t graph: it is a trapezium.', 'Area of a triangle = ½ × base × height.'] },
  { id: 'PHY-004', t: 'Motion', d: 3, ty: 'numerical', s: 120, iq: true, v: '0.5*10*3*3',
    q: 'A stone dropped from rest from the top of a tower travels 25 m during the LAST second before it hits the ground. How tall is the tower? (g = 10 m/s², ignore air resistance)',
    o: ['45 m', '31.25 m', '50 m', '61.25 m'], a: 0,
    e: 'If the fall lasts T seconds, distance in the last second = ½g[T² − (T − 1)²] = 5(2T − 1). Setting 5(2T − 1) = 25 gives T = 3 s. Height = ½ × 10 × 3² = 45 m. Check: in 2 s it falls 20 m, so the last second covers 45 − 20 = 25 m ✓.',
    m: 'Assuming the stone moves at a steady 25 m/s or that the last-second distance equals the height ignores that it keeps accelerating.',
    h: ['Let the total fall time be T. Write the distance fallen in T seconds and in (T − 1) seconds.', 'The difference of the two distances is 25 m: 5T² − 5(T − 1)² = 25.'] },
  { id: 'PHY-005', t: 'Motion', d: 3, ty: 'reasoning', s: 90, v: '(150+100)/(20+30)',
    q: 'Train A (150 m long, 20 m/s) and train B (100 m long, 30 m/s) move towards each other on parallel tracks. How long do they take to pass each other completely, from fronts meeting to rears separating?',
    o: ['5 s', '25 s', '8.3 s', '12.5 s'], a: 0,
    e: 'Relative speed for opposite directions = 20 + 30 = 50 m/s. To pass completely, the relative distance covered must equal the sum of the lengths, 250 m. Time = 250 ÷ 50 = 5 s.',
    m: '25 s uses the relative speed for trains moving in the SAME direction (30 − 20 = 10 m/s).',
    h: ['Imagine sitting on train A: how fast does B approach you?', 'The distance to cover is the total length of both trains.'] },
  { id: 'PHY-006', t: 'Motion', d: 1, ty: 'mcq', s: 30,
    q: 'A car goes round a circular roundabout at a constant speed of 30 km/h. Which statement is correct?',
    o: ['Its velocity is constant, so it is not accelerating.', 'Its velocity changes because its direction changes, so it is accelerating.', 'It is accelerating only if its speed increases.', 'Its acceleration is along its direction of motion.'], a: 1,
    e: 'Velocity is a vector. In circular motion the direction keeps changing, so velocity changes and the car accelerates even at constant speed. This (centripetal) acceleration points towards the centre of the circle, perpendicular to the motion.',
    m: 'Acceleration is not just “speeding up”; any change of velocity — including a change of direction — is acceleration.',
    h: ['Is velocity a scalar or a vector?'] },
  { id: 'PHY-007', t: 'Motion', d: 2, ty: 'numerical', s: 70, v: '(72/3.6)*4/2',
    q: 'A car travelling at 72 km/h brakes with uniform deceleration and stops in 4 s. How far does it travel while braking?',
    o: ['40 m', '80 m', '144 m', '20 m'], a: 0,
    e: '72 km/h = 72 × 1000/3600 = 20 m/s. With uniform deceleration, average speed = (20 + 0)/2 = 10 m/s. Distance = 10 × 4 = 40 m.',
    m: '144 m comes from using 72 directly without converting km/h to m/s; 80 m forgets that the speed falls to zero.',
    h: ['Convert km/h to m/s by dividing by 3.6.', 'Average speed = (initial + final)/2 for uniform deceleration.'] },
  { id: 'PHY-008', t: 'Motion', d: 3, ty: 'what-if', s: 60, iq: true, v: '10*(72/36)**2',
    q: 'A car braking at 36 km/h stops in 10 m. If the driver brakes with exactly the same deceleration from 72 km/h, what is the braking distance?',
    o: ['20 m', '40 m', '14.1 m', '80 m'], a: 1,
    e: 'From v² = u² + 2as with v = 0: s = u²/(2a). For the same deceleration, s ∝ u². Doubling the speed multiplies the braking distance by 2² = 4, so 10 m × 4 = 40 m. This is why speed limits matter so much near schools.',
    m: 'Doubling speed does not double braking distance — kinetic energy (and so the braking distance) grows with the SQUARE of speed.',
    h: ['Which equation links speed and distance without time?', 'With v = 0, s = u²/2a. What happens to u²?'] },
  { id: 'PHY-009', t: 'Motion', d: 1, ty: 'mcq', s: 25,
    q: 'What does the slope of a distance–time graph represent?',
    o: ['Acceleration', 'Speed', 'Distance travelled', 'Force'], a: 1,
    e: 'Slope = change in distance ÷ change in time = speed. A steeper line means a faster object; a horizontal line means the object is at rest. (The slope of a velocity–time graph gives acceleration.)',
    m: 'Students often mix this up with the velocity–time graph, whose slope is acceleration and whose area is displacement.',
    h: ['Slope = rise ÷ run. What is distance ÷ time?'] },
  { id: 'PHY-010', t: 'Motion', d: 2, ty: 'statement', s: 70,
    q: 'Consider the statements:\nI. A body can have zero velocity and a non-zero acceleration at the same instant.\nII. A body moving at constant speed cannot be accelerating.\nIII. Acceleration is always in the direction of motion.\nWhich are correct?',
    o: ['Only I', 'I and II', 'II and III', 'I, II and III'], a: 0,
    e: 'I is true: a ball thrown upward has v = 0 at the top but a = g downward. II is false: uniform circular motion has constant speed but is accelerated. III is false: a braking car accelerates opposite to its motion, and in circular motion acceleration is perpendicular to motion.',
    m: 'It is tempting to think “stopped” means “no acceleration”, but acceleration depends on how velocity is changing, not on its current value.',
    h: ['Think of a ball at the very top of its flight.', 'Think of a car going round a bend at steady speed.'] },

  // ---------------------------------------------------------------- Force & Newton's laws
  { id: 'PHY-011', t: "Force & Newton's Laws", d: 1, ty: 'application', s: 30,
    q: 'A standing passenger falls backwards when a stationary bus starts suddenly. This is best explained by:',
    o: ['inertia of rest', 'inertia of motion', "Newton's third law", 'friction from the floor pushing backwards'], a: 0,
    e: 'The bus floor drags the passenger’s feet forward, but the upper body tends to stay at rest because of inertia (Newton’s first law). The body therefore appears to fall backwards relative to the bus.',
    m: 'No backward force pushes the passenger; the upper body simply resists the change from rest.',
    h: ['Which part of the body is pulled forward by the bus, and which is not?'] },
  { id: 'PHY-012', t: "Force & Newton's Laws", d: 2, ty: 'numerical', s: 60, v: '0.15*20/0.1',
    q: 'A 150 g cricket ball moving at 20 m/s is caught and brought to rest in 0.1 s. What is the average force exerted by the fielder’s hands?',
    o: ['30 N', '3 N', '300 N', '0.3 N'], a: 0,
    e: 'Change in momentum = m × v = 0.15 kg × 20 m/s = 3 kg m/s. Average force = Δp/Δt = 3/0.1 = 30 N.',
    m: '300 N comes from using 150 instead of 0.15 kg and dividing wrongly; always convert grams to kilograms.',
    h: ['Force = change in momentum ÷ time.', 'Convert 150 g to kg first.'] },
  { id: 'PHY-013', t: "Force & Newton's Laws", d: 2, ty: 'application', s: 40,
    q: 'A fielder pulls his hands back while catching a fast cricket ball. Why does this reduce the sting?',
    o: ['It reduces the ball’s change in momentum.', 'It increases the time over which the momentum changes, reducing the force.', 'It reduces the mass of the ball relative to the hands.', 'It converts the ball’s momentum into heat.'], a: 1,
    e: 'The ball must lose all its momentum either way (Δp is fixed). Since F = Δp/Δt, spreading the stop over a longer time Δt reduces the average force on the hands. Airbags, crumple zones and sand pits for long jumpers use the same idea.',
    m: 'The momentum change is the same whether or not the hands move back — only the time, and therefore the force, changes.',
    h: ['Is the ball’s total change in momentum different?', 'F = Δp ÷ Δt.'] },
  { id: 'PHY-014', t: "Force & Newton's Laws", d: 2, ty: 'numerical', s: 60, v: '0.02*500/5',
    q: 'A 20 g bullet leaves a 5 kg rifle at 500 m/s. With what speed does the rifle recoil?',
    o: ['2 m/s', '0.2 m/s', '20 m/s', '5 m/s'], a: 0,
    e: 'Momentum before firing = 0, so after firing the momenta are equal and opposite: 0.02 × 500 = 5 × v → v = 10/5 = 2 m/s, backwards.',
    m: 'Using 20 instead of 0.02 kg gives a huge recoil — always convert mass to kilograms.',
    h: ['Total momentum before firing is zero.', 'm_bullet × v_bullet = m_rifle × v_rifle.'] },
  { id: 'PHY-015', t: "Force & Newton's Laws", d: 3, ty: 'reasoning', s: 90, iq: true, v: '2*10/5',
    q: 'Blocks of 3 kg and 2 kg touch each other on a frictionless floor. A 10 N horizontal push is applied to the 3 kg block, so both move together. What force does the 3 kg block exert on the 2 kg block?',
    o: ['4 N', '6 N', '10 N', '2 N'], a: 0,
    e: 'Acceleration of the pair = 10 N ÷ 5 kg = 2 m/s². The only horizontal force on the 2 kg block is the push from the 3 kg block, which must give it 2 m/s²: F = 2 × 2 = 4 N. (The 3 kg block feels 10 N forward and 4 N backward: net 6 N = 3 × 2 ✓.)',
    m: 'The full 10 N is not passed on: part of it is needed to accelerate the 3 kg block itself.',
    h: ['First find the common acceleration of both blocks.', 'Now apply F = ma to the 2 kg block alone.'] },
  { id: 'PHY-016', t: "Force & Newton's Laws", d: 2, ty: 'assertion-reason', s: 60,
    q: 'Assertion (A): A person standing on a weighing scale in a lift reads more than their true weight while the lift accelerates upward.\nReason (R): To accelerate the person upward, the normal force from the scale must be greater than the person’s weight.',
    o: ['Both A and R are true, and R correctly explains A.', 'Both A and R are true, but R does not explain A.', 'A is true, but R is false.', 'A is false, but R is true.'], a: 0,
    e: 'Net upward force = N − mg = ma, so N = m(g + a) > mg. The scale reads the normal force N, so it shows more than the true weight. R is exactly the reason for A.',
    m: 'The scale does not measure mass or gravity directly — it measures the push it must give you.',
    h: ['Write Newton’s second law for the person: which two forces act?'] },
  { id: 'PHY-017', t: "Force & Newton's Laws", d: 3, ty: 'what-if', s: 75, iq: true, v: '2*4/80', vOnly: true,
    q: 'An 80 kg astronaut floating at rest outside a space station throws a 2 kg wrench away at 4 m/s. What happens to the astronaut?',
    o: ['Moves at 0.1 m/s in the opposite direction', 'Moves at 0.1 m/s in the same direction as the wrench', 'Stays still, because there is no air to push against', 'Moves at 4 m/s in the opposite direction'], a: 0,
    e: 'Total momentum starts at zero and is conserved (no external force). 2 × 4 = 80 × v gives v = 0.1 m/s, opposite to the wrench. Rockets work the same way — they need no air to push on.',
    m: 'Propulsion does not need air. The thrown object pushes back on the thrower (Newton’s third law), in a vacuum too.',
    h: ['Is any external force acting on astronaut + wrench?', 'Momentum before = momentum after = 0.'] },
  { id: 'PHY-018', t: "Force & Newton's Laws", d: 1, ty: 'mcq', s: 30,
    q: 'Why do action and reaction forces never cancel each other out?',
    o: ['They act on different bodies.', 'Reaction is always slightly smaller than action.', 'They act at different times.', 'They act in the same direction.'], a: 0,
    e: 'Newton’s third-law forces are equal in size and opposite in direction, but each acts on a DIFFERENT body. Forces can only cancel if they act on the same body.',
    m: 'Equal and opposite does not mean balanced: balanced forces must act on the same object.',
    h: ['When you push a wall, which object feels your push and which feels the wall’s push?'] },
  { id: 'PHY-019', t: "Force & Newton's Laws", d: 3, ty: 'reasoning', s: 80,
    q: 'A horse pulls a cart. By Newton’s third law the cart pulls back on the horse with an equal force. Why, then, can the horse–cart system accelerate forward?',
    o: ['Because the horse’s pull is slightly larger than the cart’s pull.', 'Because the ground pushes the horse forward (friction) more than the ground’s friction holds the cart back.', 'Because action and reaction cancel, leaving no force.', 'Because the cart’s mass is smaller than the horse’s.'], a: 1,
    e: 'The pull of horse on cart and cart on horse are internal to the system and always equal. The system accelerates because of EXTERNAL forces: the horse pushes the ground backwards, so the ground pushes the horse forwards. If that forward friction exceeds the rolling resistance on the cart, the system accelerates.',
    m: 'The third-law pair (horse ↔ cart) never decides whether the system moves; only external forces do.',
    h: ['Draw the forces on the horse alone. Which force points forward?'] },
  { id: 'PHY-020', t: "Force & Newton's Laws", d: 1, ty: 'numerical', s: 40, v: '(30-10)/5',
    q: 'A 5 kg box is pushed along the floor with a horizontal force of 30 N while friction opposes it with 10 N. What is its acceleration?',
    o: ['4 m/s²', '6 m/s²', '8 m/s²', '2 m/s²'], a: 0,
    e: 'Net force = 30 − 10 = 20 N. a = F/m = 20/5 = 4 m/s².',
    m: '6 m/s² ignores friction; Newton’s second law uses the NET force.',
    h: ['Find the net force first.'] },
  { id: 'PHY-021', t: "Force & Newton's Laws", d: 3, ty: 'interdisciplinary', s: 80, v: '5*15/0.1',
    q: 'In a crash, a passenger’s 5 kg head moving at 15 m/s is stopped by an airbag in 0.1 s instead of by the dashboard in 0.01 s. What is the average force on the head with the airbag?',
    o: ['750 N', '7500 N', '75 N', '1500 N'], a: 0,
    e: 'Δp = 5 × 15 = 75 kg m/s in both cases. With the airbag F = 75/0.1 = 750 N; with the dashboard F = 75/0.01 = 7500 N. Increasing the stopping time tenfold reduces the force tenfold — the physics behind car safety design.',
    m: '7500 N is the dashboard force. The airbag does not change the momentum lost, only the time taken.',
    h: ['Momentum change is the same in both cases.', 'F = Δp/Δt with Δt = 0.1 s.'] },

  // ---------------------------------------------------------------- Gravitation
  { id: 'PHY-022', t: 'Gravitation', d: 1, ty: 'mcq', s: 25,
    q: 'An astronaut has a mass of 60 kg on Earth. What is her mass on the Moon, where gravity is about one-sixth as strong?',
    o: ['60 kg', '10 kg', '360 kg', '0 kg'], a: 0,
    e: 'Mass is the amount of matter and does not change with location. Her WEIGHT on the Moon is about one-sixth of her weight on Earth (≈ 98 N instead of ≈ 588 N), but her mass stays 60 kg.',
    m: 'Mass and weight are different quantities: weight is a force (N) that depends on g; mass (kg) does not.',
    h: ['Does the amount of matter in her body change?'] },
  { id: 'PHY-023', t: 'Gravitation', d: 2, ty: 'numerical', s: 50, v: '2*2**2',
    q: 'The gravitational force between two bodies is F. If the mass of one body is doubled and the distance between them is halved, the new force is:',
    o: ['8F', '4F', '2F', '16F'], a: 0,
    e: 'F ∝ m₁m₂/r². Doubling one mass multiplies F by 2; halving r multiplies F by 1/(½)² = 4. New force = 2 × 4 × F = 8F.',
    m: 'Halving the distance quadruples the force (inverse SQUARE), not doubles it.',
    h: ['Treat each change separately and multiply the factors.'] },
  { id: 'PHY-024', t: 'Gravitation', d: 3, ty: 'numerical', s: 100, iq: true, v: '9.8*2',
    q: 'A newly discovered planet has the same average density as Earth but twice Earth’s radius. What is the acceleration due to gravity on its surface? (g on Earth = 9.8 m/s²)',
    o: ['19.6 m/s²', '4.9 m/s²', '39.2 m/s²', '9.8 m/s²'], a: 0,
    e: 'g = GM/R² and M = ρ × (4/3)πR³, so g = (4/3)πGρR — proportional to R for a fixed density. Doubling R doubles g: 2 × 9.8 = 19.6 m/s². (The mass becomes 8 times larger, but the radius-squared term divides by 4.)',
    m: '4.9 m/s² assumes the mass stays the same while the radius doubles; but at the same density, a bigger planet has much more mass.',
    h: ['Write the planet’s mass in terms of density and radius.', 'Substitute into g = GM/R² — what power of R remains?'] },
  { id: 'PHY-025', t: 'Gravitation', d: 1, ty: 'experiment', s: 40,
    q: 'A feather and a coin are released together inside a long tube from which all the air has been pumped out. What is observed?',
    o: ['The coin lands first.', 'The feather lands first.', 'Both land together.', 'The feather floats.'], a: 2,
    e: 'Without air resistance, every object near Earth’s surface falls with the same acceleration g, whatever its mass. In air the feather falls slowly only because air resistance is large compared with its tiny weight.',
    m: 'Heavier objects do not fall faster: a larger mass has a proportionally larger weight, so a = W/m = g is the same.',
    h: ['What slows the feather down in ordinary air?'] },
  { id: 'PHY-026', t: 'Gravitation', d: 3, ty: 'numerical', s: 100, v: '6400',
    q: 'At what height above Earth’s surface does the acceleration due to gravity fall to one-quarter of its surface value? (Earth’s radius ≈ 6400 km)',
    o: ['6400 km', '3200 km', '12,800 km', '1600 km'], a: 0,
    e: 'g ∝ 1/r², where r is distance from Earth’s CENTRE. For g to become g/4, r must double: r = 2R. Height above the surface = 2R − R = R = 6400 km.',
    m: '12,800 km is the distance from the centre, not the height above the surface.',
    h: ['Gravity depends on distance from the centre of the Earth.', 'For ¼ of g, by what factor must that distance grow?'] },
  { id: 'PHY-027', t: 'Gravitation', d: 2, ty: 'statement', s: 60,
    q: 'Consider:\nI. Your weight can change from place to place on Earth.\nII. g is slightly greater at the poles than at the equator.\nIII. The universal gravitational constant G decreases with altitude.\nWhich are correct?',
    o: ['I and II only', 'I and III only', 'II and III only', 'I, II and III'], a: 0,
    e: 'I: weight = mg and g varies, so weight varies. II: Earth is slightly flattened and spinning, so g ≈ 9.83 m/s² at the poles vs ≈ 9.78 m/s² at the equator. III: G is a universal constant (6.67 × 10⁻¹¹ N m² kg⁻²); it is g, not G, that changes.',
    m: 'Mixing up g (local, variable) and G (universal constant) is one of the most common errors in gravitation.',
    h: ['Which symbol is a universal constant: g or G?'] },
  { id: 'PHY-028', t: 'Gravitation', d: 3, ty: 'what-if', s: 70, iq: true,
    q: 'A simple pendulum of fixed length is taken to a planet where the acceleration due to gravity is four times that on Earth. What happens to its time period?',
    o: ['It halves.', 'It doubles.', 'It becomes one-quarter.', 'It stays the same, because the length is unchanged.'], a: 0,
    e: 'T = 2π√(L/g). With g four times larger, √(1/4) = ½, so the period halves: the pendulum swings faster because the stronger gravity pulls it back more quickly.',
    m: 'The period depends on the square ROOT of g, not on g directly, so ×4 gravity gives ½ the period, not ¼.',
    h: ['Recall T = 2π√(L/g).', 'What is √(1/4)?'] },
  { id: 'PHY-029', t: 'Gravitation', d: 2, ty: 'numerical', s: 45, v: 'Math.sqrt(2*80/10)',
    q: 'A stone is dropped from rest from a cliff 80 m high. How long does it take to reach the ground? (g = 10 m/s², ignore air resistance)',
    o: ['4 s', '8 s', '16 s', '2.8 s'], a: 0,
    e: 'h = ½gt² → 80 = 5t² → t² = 16 → t = 4 s.',
    m: '8 s comes from forgetting the ½ in h = ½gt²; 16 s forgets to take the square root.',
    h: ['Use h = ½gt².'] },

  // ---------------------------------------------------------------- Pressure & Buoyancy
  { id: 'PHY-030', t: 'Pressure & Buoyancy', d: 1, ty: 'application', s: 30,
    q: 'Why does a sharp knife cut vegetables more easily than a blunt one, for the same push?',
    o: ['The sharp edge has a smaller area, so the pressure is greater.', 'The sharp edge has a larger area, so the force is greater.', 'A sharp knife is heavier.', 'A sharp knife has less friction, so the force is greater.'], a: 0,
    e: 'Pressure = force ÷ area. The same force acting on the tiny area of a sharp edge produces a much greater pressure, enough to break the vegetable’s cells.',
    m: 'Sharpening does not change the force you apply — it changes the area over which it acts.',
    h: ['Pressure = force ÷ area. Which changes when a knife is sharpened?'] },
  { id: 'PHY-031', t: 'Pressure & Buoyancy', d: 2, ty: 'numerical', s: 60, v: '2*10/(0.1*0.2)',
    q: 'A 2 kg brick rests on a table on its face measuring 10 cm × 20 cm. What pressure does it exert on the table? (g = 10 m/s²)',
    o: ['1000 Pa', '100 Pa', '10 Pa', '4000 Pa'], a: 0,
    e: 'Weight = 2 × 10 = 20 N. Area = 0.1 m × 0.2 m = 0.02 m². Pressure = 20/0.02 = 1000 Pa.',
    m: 'Using 200 cm² without converting to m² gives 0.1 — areas must be in m² for pascals (1 m² = 10,000 cm²).',
    h: ['Find the weight (force) first.', 'Convert cm to m before multiplying.'] },
  { id: 'PHY-032', t: 'Pressure & Buoyancy', d: 2, ty: 'numerical', s: 50, v: '(1-900/1000)*100',
    q: 'Ice (density 900 kg/m³) floats in fresh water (1000 kg/m³). What percentage of an ice cube’s volume is above the water surface?',
    o: ['10%', '90%', '50%', '1%'], a: 0,
    e: 'For a floating body, fraction submerged = ρ_body/ρ_liquid = 900/1000 = 0.9, i.e. 90% under water. So 10% is above the surface — the origin of “the tip of the iceberg”.',
    m: '90% is the fraction BELOW the surface.',
    h: ['Fraction submerged = density of body ÷ density of liquid.'] },
  { id: 'PHY-033', t: 'Pressure & Buoyancy', d: 3, ty: 'what-if', s: 90, iq: true,
    q: 'A glass is filled to the brim with water with an ice cube floating in it. The ice cube melts completely. What happens?',
    o: ['Water overflows.', 'The water level falls.', 'The water level stays exactly at the brim.', 'It depends on the room temperature.'], a: 2,
    e: 'A floating ice cube displaces its own WEIGHT of water. When it melts, it becomes water of exactly that weight, which occupies exactly the volume it was already displacing. So the level does not change. (Melting LAND ice, which is not floating, does raise sea level.)',
    m: 'The part of the ice above water seems as if it should overflow, but ice is less dense than water — it shrinks to fill exactly the “hole” it made.',
    h: ['How much water does a floating object displace — its volume or its weight?', 'What weight of water does the cube become when it melts?'] },
  { id: 'PHY-034', t: 'Pressure & Buoyancy', d: 3, ty: 'numerical', s: 100, iq: true, v: '10/(10-6)*1000',
    q: 'A metal object weighs 10 N in air and 6 N when fully submerged in water (density 1000 kg/m³). What is the density of the metal?',
    o: ['2500 kg/m³', '1500 kg/m³', '1667 kg/m³', '4000 kg/m³'], a: 0,
    e: 'Buoyant force = 10 − 6 = 4 N = weight of water displaced. Relative density = weight in air ÷ loss of weight in water = 10/4 = 2.5, so density = 2500 kg/m³.',
    m: '1667 kg/m³ comes from dividing by the apparent weight (6 N) instead of by the LOSS of weight (4 N).',
    h: ['The loss of weight equals the buoyant force.', 'Relative density = weight in air ÷ loss of weight in water.'] },
  { id: 'PHY-035', t: 'Pressure & Buoyancy', d: 2, ty: 'what-if', s: 60, iq: true,
    q: 'An egg sinks in a glass of tap water but floats after enough salt is dissolved. What is the best explanation?',
    o: ['Salt makes the egg lighter.', 'Salt water is denser, so the same displaced volume weighs more and gives a larger upthrust.', 'Salt reduces the surface tension of water.', 'Salt dissolves the egg shell, making it hollow.'], a: 1,
    e: 'Upthrust = volume displaced × density of liquid × g. Dissolving salt raises the density of the water. Once the liquid is denser than the egg, the upthrust on the fully submerged egg exceeds its weight and it rises until it floats.',
    m: 'The egg’s weight does not change. An object floats or sinks depending on its density compared with the LIQUID’s density.',
    h: ['Which changes: the egg or the liquid?', 'Upthrust depends on the density of the liquid.'] },
  { id: 'PHY-036', t: 'Pressure & Buoyancy', d: 3, ty: 'what-if', s: 100, iq: true,
    q: 'A boat carrying a heavy iron anchor floats in a swimming pool. The anchor is thrown overboard and sinks to the bottom. What happens to the water level in the pool?',
    o: ['It rises.', 'It falls.', 'It stays the same.', 'It rises, then returns to the original level.'], a: 1,
    e: 'In the boat, the anchor is floating indirectly, so it displaces water equal to its WEIGHT. Iron is about 8 times denser than water, so that is a large volume. On the bottom it displaces only its own VOLUME, which is much smaller. Less water is displaced, so the level falls.',
    m: 'Many expect no change because “the same things are in the pool”. What matters is how much water is displaced: weight-equivalent when floating, volume-equivalent when sunk.',
    h: ['How much water does the anchor displace while it rides in the boat?', 'How much does it displace lying on the bottom? Compare, given iron is denser than water.'] },
  { id: 'PHY-037', t: 'Pressure & Buoyancy', d: 1, ty: 'numerical', s: 40, v: '10*1000*10',
    q: 'What is the pressure due to water alone at a depth of 10 m in a lake? (density of water 1000 kg/m³, g = 10 m/s²)',
    o: ['1 × 10⁵ Pa', '1 × 10⁴ Pa', '1 × 10⁶ Pa', '1 × 10³ Pa'], a: 0,
    e: 'P = hρg = 10 × 1000 × 10 = 100,000 Pa = 1 × 10⁵ Pa — roughly the same as atmospheric pressure. So a diver at 10 m feels about twice the pressure at the surface.',
    m: 'Pressure in a liquid depends on depth, not on the size or shape of the lake.',
    h: ['Use P = hρg.'] },

  // ---------------------------------------------------------------- Work, Energy & Power
  { id: 'PHY-038', t: 'Work, Energy & Power', d: 2, ty: 'reasoning', s: 50,
    q: 'How much work does Earth’s gravity do on a satellite moving in a perfectly circular orbit during one revolution?',
    o: ['Zero, because the force is always perpendicular to the displacement', 'mgh, where h is the height of the orbit', 'Positive, because gravity pulls the satellite', 'Negative, because the satellite moves away from Earth'], a: 0,
    e: 'W = Fs cos θ. In a circular orbit, gravity points to the centre while the motion is tangential, so θ = 90° and cos 90° = 0 at every instant. No work is done, which is why the satellite’s speed stays constant.',
    m: 'A force can act continuously yet do no work if it is perpendicular to the motion.',
    h: ['What is the angle between gravity and the satellite’s velocity?'] },
  { id: 'PHY-039', t: 'Work, Energy & Power', d: 2, ty: 'numerical', s: 60, v: '0.5*1000*(20**2-10**2)/1000',
    q: 'A 1000 kg car speeds up from 10 m/s to 20 m/s. How much work must the net force do on it?',
    o: ['150 kJ', '50 kJ', '100 kJ', '200 kJ'], a: 0,
    e: 'Work–energy theorem: W = ΔKE = ½m(v² − u²) = ½ × 1000 × (400 − 100) = 150,000 J = 150 kJ.',
    m: '50 kJ uses ½m(v − u)², squaring the change in speed instead of taking the change in v².',
    h: ['Work done = change in kinetic energy.', 'Compute KE at each speed separately.'] },
  { id: 'PHY-040', t: 'Work, Energy & Power', d: 1, ty: 'numerical', s: 45, v: '200*10*15/30',
    q: 'A motor lifts a 200 kg load through a height of 15 m in 30 s at steady speed. What is the power output of the motor? (g = 10 m/s²)',
    o: ['1000 W', '100 W', '3000 W', '600 W'], a: 0,
    e: 'Work = mgh = 200 × 10 × 15 = 30,000 J. Power = work/time = 30,000/30 = 1000 W = 1 kW.',
    m: 'Forgetting g (using mass instead of weight) gives 100 W.',
    h: ['Work done against gravity = mgh.', 'Power = work ÷ time.'] },
  { id: 'PHY-041', t: 'Work, Energy & Power', d: 3, ty: 'numerical', s: 70, iq: true, v: 'Math.sqrt(2*10*0.45)',
    q: 'A pendulum bob is pulled aside until it is 45 cm higher than its lowest point and then released. Ignoring air resistance, how fast is it moving as it passes through the lowest point? (g = 10 m/s²)',
    o: ['3 m/s', '9 m/s', '4.5 m/s', '2.1 m/s'], a: 0,
    e: 'Energy conservation: mgh = ½mv², so v = √(2gh) = √(2 × 10 × 0.45) = √9 = 3 m/s. The mass cancels, and the length of the string does not matter — only the drop in height.',
    m: 'You do not need the length of the string or the mass of the bob: only the vertical height drop matters.',
    h: ['Which energy changes into which?', 'Set mgh = ½mv² and solve for v (h in metres).'] },
  { id: 'PHY-042', t: 'Work, Energy & Power', d: 3, ty: 'interdisciplinary', s: 90, v: '300*10*20/0.75/1000',
    q: 'A pump that is 75% efficient lifts 300 kg of water into a tank 20 m above the ground. How much electrical energy does it use? (g = 10 m/s²)',
    o: ['80 kJ', '60 kJ', '45 kJ', '75 kJ'], a: 0,
    e: 'Useful work = mgh = 300 × 10 × 20 = 60,000 J. Efficiency = useful output/input, so input = 60,000/0.75 = 80,000 J = 80 kJ. The extra 20 kJ is wasted, mostly as heat and sound.',
    m: '45 kJ multiplies by 0.75 instead of dividing: the input must always be LARGER than the useful output.',
    h: ['Find the useful energy first.', 'Input energy = useful energy ÷ efficiency.'] },
  { id: 'PHY-043', t: 'Work, Energy & Power', d: 1, ty: 'assertion-reason', s: 50,
    q: 'Assertion (A): A person holding a heavy suitcase while standing still does no work on the suitcase.\nReason (R): Work done is zero when the displacement is zero.',
    o: ['Both A and R are true, and R correctly explains A.', 'Both A and R are true, but R does not explain A.', 'A is true, but R is false.', 'A is false, but R is true.'], a: 0,
    e: 'W = Fs cos θ; with s = 0, W = 0 regardless of the force. The person still gets tired because muscles use chemical energy internally, but no mechanical work is done on the suitcase.',
    m: 'Feeling tired is not evidence of mechanical work.',
    h: ['Does the suitcase move?'] },

  // ---------------------------------------------------------------- Sound
  { id: 'PHY-044', t: 'Sound', d: 1, ty: 'mcq', s: 25,
    q: 'Astronauts on a spacewalk cannot hear each other directly even when shouting close by. Why?',
    o: ['Sound needs a material medium, and space is almost a vacuum.', 'Sound is too slow in space.', 'Their frequencies are too high.', 'Cosmic radiation absorbs sound.'], a: 0,
    e: 'Sound is a mechanical wave — vibrations passed from particle to particle. In the near-vacuum of space there are almost no particles, so sound cannot travel. Astronauts use radio (an electromagnetic wave), which does not need a medium.',
    m: 'Light and radio cross a vacuum because they are electromagnetic waves; sound cannot.',
    h: ['What does sound travel through?'] },
  { id: 'PHY-045', t: 'Sound', d: 1, ty: 'numerical', s: 35, v: '500*0.68',
    q: 'A sound wave has a frequency of 500 Hz and a wavelength of 0.68 m. What is its speed?',
    o: ['340 m/s', '735 m/s', '0.00136 m/s', '170 m/s'], a: 0,
    e: 'v = fλ = 500 × 0.68 = 340 m/s, the speed of sound in air at about 20 °C.',
    m: 'Dividing f by λ instead of multiplying gives a meaningless 735.',
    h: ['Use v = f × λ.'] },
  { id: 'PHY-046', t: 'Sound', d: 3, ty: 'numerical', s: 80, v: '344*0.1/2',
    q: 'The sensation of a sound persists in our brain for about 0.1 s. What is the minimum distance from a reflecting wall for a distinct echo to be heard, if the speed of sound is 344 m/s?',
    o: ['17.2 m', '34.4 m', '8.6 m', '172 m'], a: 0,
    e: 'For a distinct echo, the reflected sound must arrive at least 0.1 s after the original. In 0.1 s sound travels 34.4 m — but that is the round trip, there and back. So the wall must be at least 34.4/2 = 17.2 m away.',
    m: '34.4 m forgets that the sound has to travel to the wall AND back.',
    h: ['How far does sound go in 0.1 s?', 'An echo is a round trip.'] },
  { id: 'PHY-047', t: 'Sound', d: 3, ty: 'what-if', s: 70, iq: true,
    q: 'A sound wave passes from air into water, where sound travels about four times faster. Which describes the wave in water?',
    o: ['Same frequency, longer wavelength', 'Higher frequency, same wavelength', 'Same frequency, shorter wavelength', 'Lower frequency, longer wavelength'], a: 0,
    e: 'Frequency is set by the source and does not change when a wave crosses into a new medium (every incoming vibration produces one vibration on the other side). Since v = fλ and v increases about 4 times, λ increases about 4 times.',
    m: 'Pitch (frequency) does not change at a boundary — the wavelength changes instead.',
    h: ['What decides frequency: the source or the medium?', 'Then use v = fλ.'] },
  { id: 'PHY-048', t: 'Sound', d: 2, ty: 'numerical', s: 50, v: '1500*2/2',
    q: 'A ship’s SONAR sends an ultrasonic pulse straight down. The echo from the seabed returns after 2 s. If sound travels at 1500 m/s in sea water, how deep is the sea?',
    o: ['1500 m', '3000 m', '750 m', '6000 m'], a: 0,
    e: 'Total path = 1500 × 2 = 3000 m, which is down and back up. Depth = 3000/2 = 1500 m.',
    m: '3000 m forgets that the pulse travels the depth twice.',
    h: ['Distance = speed × time — but for which journey?'] },
  { id: 'PHY-049', t: 'Sound', d: 2, ty: 'reasoning', s: 50,
    q: 'Putting your ear to a railway line, you can hear an approaching train before you hear it through the air. Why?',
    o: ['Sound travels faster in steel than in air.', 'Steel amplifies sound.', 'Sound travels in straight lines only through solids.', 'Air absorbs all low-frequency sound.'], a: 0,
    e: 'In solids, particles are tightly bound and very stiff, so vibrations pass on quickly: sound travels at about 5000–6000 m/s in steel compared with about 340 m/s in air. The sound through the rail arrives first.',
    m: 'It is not that steel makes sound louder; the key difference is speed.',
    h: ['In which state of matter does sound travel fastest?'] },

  // ---------------------------------------------------------------- Light
  { id: 'PHY-050', t: 'Light', d: 1, ty: 'mcq', s: 30,
    q: 'Which set describes the image formed by a plane mirror?',
    o: ['Virtual, erect, laterally inverted and the same size', 'Real, inverted and the same size', 'Virtual, inverted and smaller', 'Real, erect and magnified'], a: 0,
    e: 'Reflected rays from a plane mirror diverge; they only appear to come from a point behind the mirror, so the image is virtual. It is upright, the same size, as far behind the mirror as the object is in front, and left–right reversed (lateral inversion).',
    m: 'The image is not “on” the mirror — it is located behind it.',
    h: ['Can the image be caught on a screen?'] },
  { id: 'PHY-051', t: 'Light', d: 2, ty: 'numerical', s: 40, v: '3/2.25',
    q: 'Light travels at 3 × 10⁸ m/s in vacuum and 2.25 × 10⁸ m/s in water. What is the refractive index of water?',
    o: ['1.33', '1.5', '0.75', '2.25'], a: 0,
    e: 'n = c/v = (3 × 10⁸)/(2.25 × 10⁸) = 1.33. Refractive index is always greater than 1 for a material medium because light is slower in it than in vacuum.',
    m: '0.75 is v/c, the inverse ratio.',
    h: ['n = speed in vacuum ÷ speed in medium.'] },
  { id: 'PHY-052', t: 'Light', d: 3, ty: 'numerical', s: 90, v: '1/(1/10-1/15)',
    q: 'An object is placed 15 cm in front of a convex lens of focal length 10 cm. Where is the image formed?',
    o: ['30 cm on the other side of the lens (real)', '6 cm on the same side (virtual)', '15 cm on the other side (real)', '60 cm on the other side (real)'], a: 0,
    e: 'Lens formula 1/v − 1/u = 1/f with u = −15 cm, f = +10 cm: 1/v = 1/10 − 1/15 = 1/30, so v = +30 cm. Positive v means a real image on the opposite side; magnification = v/u = −2 (inverted, twice the size).',
    m: '6 cm comes from adding 1/10 + 1/15 — the sign convention for the object distance matters.',
    h: ['Use 1/v − 1/u = 1/f with u negative.', 'The object is between f and 2f; where should the image be?'] },
  { id: 'PHY-053', t: 'Light', d: 3, ty: 'what-if', s: 80, iq: true,
    q: 'A glass convex lens (refractive index 1.5) is placed under water (refractive index 1.33). How does its behaviour change?',
    o: ['It converges light less strongly — its focal length increases.', 'It converges light more strongly — its focal length decreases.', 'It becomes a diverging lens.', 'Nothing changes; focal length depends only on the curvature.'], a: 0,
    e: 'A lens bends light because of the DIFFERENCE between its refractive index and that of the surrounding medium. Glass in water has a much smaller contrast (1.5 vs 1.33) than glass in air (1.5 vs 1.0), so rays bend less and the focal length becomes longer (about four times longer for these values). It stays converging because glass is still optically denser than water.',
    m: 'Focal length depends on the surrounding medium as well as the curvature.',
    h: ['Why does a lens bend light at all?', 'Compare the index contrast glass–air with glass–water.'] },
  { id: 'PHY-054', t: 'Light', d: 2, ty: 'reasoning', s: 50,
    q: 'Why does the clear daytime sky look blue, while the Sun looks reddish at sunset?',
    o: ['Air molecules scatter short (blue) wavelengths much more than long (red) ones.', 'The oceans reflect blue light into the sky.', 'Ozone is blue in colour.', 'Blue light travels faster through air than red light.'], a: 0,
    e: 'Small air molecules scatter light far more strongly at short wavelengths, so blue light is scattered across the sky and reaches our eyes from all directions. At sunset sunlight passes through much more air, so most blue is scattered out of the direct beam and the remaining light reaching us is reddish.',
    m: 'The sky is not blue because of reflection from the sea — the sky is blue over deserts too.',
    h: ['What happens to sunlight when it meets tiny air molecules?'] },
  { id: 'PHY-055', t: 'Light', d: 2, ty: 'numerical', s: 40, v: '-1/0.5',
    q: 'A concave (diverging) lens has a focal length of 50 cm. What is its power?',
    o: ['−2 D', '+2 D', '−0.5 D', '−50 D'], a: 0,
    e: 'P = 1/f with f in metres. A diverging lens has negative focal length: f = −0.5 m, so P = 1/(−0.5) = −2 dioptres. Such lenses correct short-sightedness.',
    m: '−50 D uses centimetres instead of metres; +2 D ignores the sign of a diverging lens.',
    h: ['Convert the focal length to metres.', 'Diverging lenses have negative focal length.'] },

  // ---------------------------------------------------------------- Electricity
  { id: 'PHY-056', t: 'Electricity', d: 1, ty: 'mcq', s: 30,
    q: 'Three different resistors are connected in series to a battery. Which quantity is the same for all three?',
    o: ['Current through each', 'Potential difference across each', 'Power dissipated in each', 'Resistance of each'], a: 0,
    e: 'In a series circuit there is only one path, so the same charge per second (current) passes through every component. The potential difference divides in proportion to the resistances (V = IR), and so does the power (P = I²R).',
    m: 'In series, current is shared equally — it is voltage that is split. In parallel it is the other way round.',
    h: ['How many paths does the current have in a series circuit?'] },
  { id: 'PHY-057', t: 'Electricity', d: 2, ty: 'what-if', s: 50, iq: true, v: '5*2',
    q: 'A wire has a resistance of 5 Ω. A second wire of the same material and the same cross-sectional area is twice as long. What is its resistance?',
    o: ['10 Ω', '2.5 Ω', '20 Ω', '5 Ω'], a: 0,
    e: 'R = ρL/A. With the same material (ρ) and area (A), resistance is directly proportional to length. Twice the length → twice the resistance = 10 Ω. Electrons have twice as far to travel through the obstructing lattice.',
    m: '20 Ω applies to a wire STRETCHED to double length, where the area also halves; here the area is unchanged.',
    h: ['Write R in terms of ρ, L and A.', 'Which of these change?'] },
  { id: 'PHY-058', t: 'Electricity', d: 3, ty: 'numerical', s: 90, v: '18/(6+6*6/(6+6))',
    q: 'Two 6 Ω resistors are connected in parallel, and this combination is connected in series with a third 6 Ω resistor across an 18 V battery. What current does the battery supply?',
    o: ['2 A', '1 A', '3 A', '6 A'], a: 0,
    e: 'Two 6 Ω in parallel: 1/R = 1/6 + 1/6 → R = 3 Ω. Adding the series 6 Ω gives 9 Ω total. I = V/R = 18/9 = 2 A.',
    m: '1 A treats all three as one series chain (18 Ω); 6 A forgets the series resistor (18 ÷ 3); 3 A uses a single 6 Ω resistor. Simplify the parallel pair first, then add the series part.',
    h: ['Simplify the parallel pair first.', 'Then add the series resistor and use I = V/R.'] },
  { id: 'PHY-059', t: 'Electricity', d: 3, ty: 'reasoning', s: 100, iq: true,
    q: 'A 100 W bulb and a 60 W bulb (both rated for 220 V) are connected in SERIES across a 220 V supply. Which glows more brightly?',
    o: ['The 60 W bulb', 'The 100 W bulb', 'Both equally', 'Neither glows at all'], a: 0,
    e: 'From P = V²/R at rated voltage, R = V²/P: the 60 W bulb has the larger resistance (≈ 807 Ω vs 484 Ω). In series, both carry the same current, so the power P = I²R is greater in the bulb with greater resistance — the 60 W bulb glows brighter. (Both glow dimmer than normal.)',
    m: 'The power rating applies only at 220 V across EACH bulb; in series neither gets its rated voltage.',
    h: ['Which bulb has the higher resistance? Use R = V²/P.', 'In series, which quantity is common to both bulbs?'] },
  { id: 'PHY-060', t: 'Electricity', d: 2, ty: 'numerical', s: 40, v: '1500*2/1000',
    q: 'A 1500 W electric heater is used for 2 hours. How much electrical energy does it use, in kilowatt-hours?',
    o: ['3 kWh', '3000 kWh', '0.75 kWh', '30 kWh'], a: 0,
    e: 'Energy = power × time = 1.5 kW × 2 h = 3 kWh (3 “units” on an electricity bill). In joules this is 3 × 3.6 × 10⁶ = 1.08 × 10⁷ J.',
    m: '3000 kWh forgets to convert watts to kilowatts.',
    h: ['Convert 1500 W to kW.', 'Energy (kWh) = kW × hours.'] },

  // ---------------------------------------------------------------- Magnetism
  { id: 'PHY-061', t: 'Magnetism', d: 1, ty: 'mcq', s: 30,
    q: 'Why can two magnetic field lines never cross each other?',
    o: ['At a crossing point the field would have two directions at once, which is impossible.', 'Field lines repel each other.', 'Field lines only exist outside the magnet.', 'Field lines always run parallel.'], a: 0,
    e: 'The tangent to a field line at any point gives the direction a compass needle would point. If two lines crossed, a compass at that point would have to point two ways at once — impossible, since the field has a single direction at each point.',
    m: 'Field lines are a model of direction; they are not physical strings that push each other.',
    h: ['What does the direction of a field line at a point tell you?'] },
  { id: 'PHY-062', t: 'Magnetism', d: 2, ty: 'application', s: 45,
    q: 'Which change would NOT make an electromagnet stronger?',
    o: ['Replacing the soft-iron core with a copper core', 'Increasing the number of turns of wire', 'Increasing the current', 'Winding the coil more tightly around the same soft-iron core'], a: 0,
    e: 'An electromagnet’s strength increases with current and with the number of turns, and a soft-iron core concentrates the field enormously because iron is magnetic. Copper is non-magnetic, so replacing iron with copper would make the electromagnet much WEAKER.',
    m: 'Copper is an excellent conductor, but conducting electricity is not the same as being magnetic.',
    h: ['Which of these materials is attracted to a magnet?'] },
  { id: 'PHY-063', t: 'Magnetism', d: 3, ty: 'experiment', s: 80,
    q: 'A coil is connected to a sensitive galvanometer. Consider:\nI. Pushing a bar magnet into the coil deflects the needle.\nII. Holding the magnet still inside the coil keeps the needle deflected.\nIII. Pulling the magnet out deflects the needle the opposite way.\nIV. Moving the magnet faster gives a larger deflection.\nWhich are correct?',
    o: ['I, III and IV only', 'I, II and III only', 'I and II only', 'All four'], a: 0,
    e: 'Electromagnetic induction (Faraday): a current is induced only while the magnetic field through the coil is CHANGING. A stationary magnet causes no change, so no current (II is false). Reversing the motion reverses the current (III), and faster change gives a larger induced current (IV).',
    m: 'A magnet sitting in a coil does not produce electricity — only change does.',
    h: ['What has to be changing for a current to be induced?'] },
  { id: 'PHY-064', t: 'Magnetism', d: 2, ty: 'mcq', s: 35,
    q: 'Fleming’s left-hand rule is used to find the direction of:',
    o: ['the force on a current-carrying conductor in a magnetic field', 'the induced current in a generator', 'the magnetic field around a straight wire', 'the poles of a bar magnet'], a: 0,
    e: 'Left hand: First finger = Field, seCond finger = Current, thuMb = Motion (force). It gives the force on a current-carrying conductor — the principle of the electric motor. The RIGHT-hand rule gives induced current (generators).',
    m: 'Left hand → motors; right hand → generators.',
    h: ['Which device turns current into motion?'] },

  // ---------------------------------------------------------------- Heat
  { id: 'PHY-065', t: 'Heat', d: 1, ty: 'mcq', s: 25,
    q: 'Heat from the Sun reaches Earth through the near-vacuum of space by:',
    o: ['radiation', 'conduction', 'convection', 'both conduction and convection'], a: 0,
    e: 'Conduction and convection need particles of matter. Radiation is the transfer of energy by electromagnetic waves (infrared, visible light), which travel through a vacuum.',
    m: 'Convection needs a fluid to flow; there is almost none in space.',
    h: ['Which method of heat transfer needs no medium?'] },
  { id: 'PHY-066', t: 'Heat', d: 2, ty: 'numerical', s: 50, v: '2*4200*(70-20)/1000',
    q: 'How much heat is needed to raise the temperature of 2 kg of water from 20 °C to 70 °C? (specific heat capacity of water = 4200 J kg⁻¹ °C⁻¹)',
    o: ['420 kJ', '42 kJ', '210 kJ', '840 kJ'], a: 0,
    e: 'Q = mcΔT = 2 × 4200 × 50 = 420,000 J = 420 kJ.',
    m: '840 kJ uses 100 °C rise or doubles twice; ΔT is 70 − 20 = 50 °C.',
    h: ['Q = m × c × ΔT.'] },
  { id: 'PHY-067', t: 'Heat', d: 3, ty: 'numerical', s: 80, iq: true, v: '(1*80+3*20)/(1+3)',
    q: '1 kg of water at 80 °C is mixed with 3 kg of water at 20 °C in an insulated container. What is the final temperature?',
    o: ['35 °C', '50 °C', '40 °C', '30 °C'], a: 0,
    e: 'Heat lost by hot water = heat gained by cold water: 1 × c × (80 − T) = 3 × c × (T − 20) → 80 − T = 3T − 60 → T = 35 °C. It is a weighted average of the temperatures, weighted by mass.',
    m: '50 °C is the simple average, which only applies to equal masses.',
    h: ['Heat lost = heat gained.', 'Should the answer be closer to 80 or to 20? Why?'] },
  { id: 'PHY-068', t: 'Heat', d: 1, ty: 'application', s: 30,
    q: 'Why are small gaps left between sections of railway track?',
    o: ['To allow the rails to expand in hot weather without buckling', 'To drain rainwater', 'To reduce the noise of trains', 'To save steel'], a: 0,
    e: 'Metals expand when heated. Without gaps, rails heated by summer sun would push against each other and buckle. (Modern continuous welded rail is pre-stressed to manage the same problem.)',
    m: '',
    h: ['What happens to the length of a steel rail when it gets hot?'] },
  { id: 'PHY-069', t: 'Heat', d: 3, ty: 'what-if', s: 70, iq: true,
    q: 'What would happen to the boiling point of water if the atmospheric pressure above it were increased?',
    o: ['It would rise above 100 °C.', 'It would fall below 100 °C.', 'It would stay at 100 °C, a fixed property of water.', 'Water would no longer boil at any temperature.'], a: 0,
    e: 'Water boils when its vapour pressure equals the pressure above it. Higher outside pressure means the water must be hotter before its vapour pressure is high enough. That is why a pressure cooker (≈ 2 atm) cooks at about 120 °C, while at high altitude water boils below 100 °C.',
    m: '100 °C is the boiling point only at standard atmospheric pressure — not a fixed constant.',
    h: ['When does a liquid boil: think about bubbles of vapour pushing against the surroundings.', 'Compare cooking on a mountain with a pressure cooker.'] },
];
